2	
3	// Matches Unicode general categories {Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs} —
4	// the set of characters Python's str repr() escapes instead of printing.
5	const ESCAPE_CATEGORY_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
6	
7	function hex(n, width) {
8	  return n.toString(16).padStart(width, '0');
9	}
