11	// Python repr() of a bytes object.
12	// bytes: Uint8Array. Returns e.g. "b'xn--rsum-bpad.com'".
13	export function bytesRepr(bytes) {
14	  let hasSingle = false;
15	  let hasDouble = false;
16	  for (const b of bytes) {
17	    if (b === 0x27) hasSingle = true;
18	    else if (b === 0x22) hasDouble = true;
19	  }
20	  const quote = hasSingle && !hasDouble ? '"' : "'";
21	  const quoteCode = quote.charCodeAt(0);
22	
23	  let out = 'b' + quote;
24	  for (const b of bytes) {
25	    if (b === 0x5c) {
26	      out += '\\\\';
27	    } else if (b === quoteCode) {
28	      out += '\\' + quote;
29	    } else if (b === 0x09) {
30	      out += '\\t';
31	    } else if (b === 0x0a) {
32	      out += '\\n';
33	    } else if (b === 0x0d) {
34	      out += '\\r';
35	    } else if (b >= 0x20 && b <= 0x7e) {
36	      out += String.fromCharCode(b);
37	    } else {
38	      out += '\\x' + hex(b, 2);
39	    }
40	  }
41	  return out + quote;
42	}
