44	// Python repr() of a str object.
45	export function strRepr(str) {
46	  const hasSingle = str.includes("'");
47	  const hasDouble = str.includes('"');
48	  const quote = hasSingle && !hasDouble ? '"' : "'";
49	
50	  let out = quote;
51	  for (const ch of str) {
52	    const cp = ch.codePointAt(0);
53	    if (ch === '\\') {
54	      out += '\\\\';
55	    } else if (ch === quote) {
56	      out += '\\' + quote;
57	    } else if (ch === '\n') {
58	      out += '\\n';
59	    } else if (ch === '\r') {
60	      out += '\\r';
61	    } else if (ch === '\t') {
62	      out += '\\t';
63	    } else if (ch !== ' ' && ESCAPE_CATEGORY_RE.test(ch)) {
64	      if (cp < 0x100) {
65	        out += '\\x' + hex(cp, 2);
66	      } else if (cp < 0x10000) {
67	        out += '\\u' + hex(cp, 4);
68	      } else {
69	        out += '\\U' + hex(cp, 8);
70	      }
71	    } else {
72	      out += ch;
73	    }
74	  }
75	  return out + quote;
76	}

1	// Replicates Python 3.12+ argparse behavior for this exact parser:
2	//   add_argument('--domain', type=str, required=True)
3	//   add_argument('--mode', type=str, required=True,
4	//                choices=['encode', 'decode', 'both'])
5	//   add_argument('--transitional', type=bool, required=False, default=False)
6	//   add_argument('--strict', type=bool, required=False, default=False)
7	// plus the automatic -h/--help.
8	
9	import { strRepr } from './pyfmt.mjs';
10	
11	const TEXT_WIDTH = 78; // terminal width 80 minus 2
12	
13	const LONG_OPTIONS = ['--help', '--domain', '--mode', '--transitional', '--strict'];
14	const MODE_CHOICES = ['encode', 'decode', 'both'];
15	
16	// A token starting with '-' counts as a value only if it is exactly '-'
17	// or looks like a negative number.
18	const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;
19	
20	function looksLikeOptionString(token) {
21	  if (!token.startsWith('-')) return false;
22	  if (token === '-') return false;
23	  if (NEGATIVE_NUMBER_RE.test(token)) return false;
24	  return true;
25	}
26	
27	// Greedy word-wrap of the usage line, mirroring argparse's HelpFormatter:
28	// pack parts so each line (including the indent) stays <= TEXT_WIDTH chars.
29	function formatUsage(prog) {
30	  const prefix = `usage: ${prog} `;
31	  const parts = [
32	    '[-h]',
33	    '--domain DOMAIN',
34	    '--mode {encode,decode,both}',
35	    '[--transitional TRANSITIONAL]',
36	    '[--strict STRICT]',
37	  ];
38	  const indent = ' '.repeat(prefix.length);
39	
40	  const lines = [];
41	  let line = [];
42	  let lineLen = prefix.length - 1;
43	  for (const part of parts) {
44	    if (lineLen + 1 + part.length > TEXT_WIDTH && line.length > 0) {
45	      lines.push(indent + line.join(' '));
46	      line = [];
47	      lineLen = indent.length - 1;
48	    }
49	    line.push(part);
50	    lineLen += 1 + part.length;
51	  }
52	  if (line.length > 0) lines.push(indent + line.join(' '));
53	
54	  // First line carries the real prefix instead of the blank indent.
55	  lines[0] = prefix + lines[0].slice(indent.length);
56	  return lines.join('\n') + '\n';
57	}
58	
59	function formatHelp(prog) {
60	  return (
61	    formatUsage(prog) +
62	    '\n' +
63	    'options:\n' +
64	    '  -h, --help'.padEnd(24) + 'show this help message and exit\n' +
65	    '  --domain DOMAIN\n' +
66	    '  --mode {encode,decode,both}\n' +
67	    '  --transitional TRANSITIONAL\n' +
68	    '  --strict STRICT\n'
69	  );
70	}
71	
72	function printHelpAndExit(prog) {
73	  process.stdout.write(formatHelp(prog));
74	  process.exit(0);
75	}
76	
77	function errorAndExit(prog, message) {
78	  process.stderr.write(formatUsage(prog));
79	  process.stderr.write(`${prog}: error: ${message}\n`);
80	  process.exit(2);
81	}
82	
83	// argv: process.argv.slice(2). Returns { domain, mode, transitional, strict }.
84	// transitional/strict are JS booleans computed as valueString.length > 0,
85	// replicating Python's bool(str) quirk for type=bool.
86	export function parseArgs(argv, prog) {
87	  const result = { domain: undefined, mode: undefined, transitional: false, strict: false };
88	  const extras = [];
89	
90	  let i = 0;
91	  while (i < argv.length) {
92	    const token = argv[i];
93	
94	    // '--' separator: it and everything after it are unrecognized here,
95	    // since this parser defines no positionals.
96	    if (token === '--') {
97	      for (let j = i; j < argv.length; j++) extras.push(argv[j]);
98	      break;
99	    }
100	
101	    if (token.startsWith('--')) {
102	      let name = token;
103	      let explicitValue = null;
104	      const eq = token.indexOf('=');
105	      if (eq !== -1) {
106	        name = token.slice(0, eq);
107	        explicitValue = token.slice(eq + 1);
108	      }
109	
110	      let matched = null;
111	      if (LONG_OPTIONS.includes(name)) {
112	        matched = name;
113	      } else {
114	        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
115	        if (candidates.length === 1) {
116	          matched = candidates[0];
117	        } else if (candidates.length > 1) {
118	          errorAndExit(prog, `ambiguous option: ${token} could match ${candidates.join(', ')}`);
119	        } else {
120	          extras.push(token);
121	          i++;
122	          continue;
123	        }
124	      }
125	
126	      if (matched === '--help') {
127	        printHelpAndExit(prog);
128	      }
129	
130	      let value;
131	      if (explicitValue !== null) {
132	        value = explicitValue;
133	      } else {
134	        const next = argv[i + 1];
135	        if (next === undefined || looksLikeOptionString(next)) {
136	          errorAndExit(prog, `argument ${matched}: expected one argument`);
137	        }
138	        value = next;
139	        i++;
140	      }
141	
142	      if (matched === '--domain') {
143	        result.domain = value;
144	      } else if (matched === '--mode') {
145	        if (!MODE_CHOICES.includes(value)) {
146	          errorAndExit(
147	            prog,
148	            `argument --mode: invalid choice: ${strRepr(value)} ` +
149	              `(choose from ${MODE_CHOICES.map(strRepr).join(', ')})`,
150	          );
151	        }
152	        result.mode = value;
153	      } else if (matched === '--transitional') {
154	        result.transitional = value.length > 0;
155	      } else if (matched === '--strict') {
156	        result.strict = value.length > 0;
157	      }
158	      i++;
159	      continue;
160	    }
161	
162	    if (token === '-h') {
163	      printHelpAndExit(prog);
164	    }
165	
166	    // Unknown short option, '-', a negative number, or a stray positional:
167	    // all collect as unrecognized arguments.
168	    extras.push(token);
169	    i++;
170	  }
171	
172	  const missing = [];
173	  if (result.domain === undefined) missing.push('--domain');
174	  if (result.mode === undefined) missing.push('--mode');
175	  if (missing.length > 0) {
176	    errorAndExit(prog, `the following arguments are required: ${missing.join(', ')}`);
177	  }
178	
179	  if (extras.length > 0) {
180	    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
181	  }
182	
183	  return result;
184	}
